npt_encode_ID3D11CryptoSession_GetCryptoSessionHandle(struct npt_cs_encoder *enc,
                                                      uint32_t cmd_flags,
                                                      npt_object_id object_id,
                                                      HANDLE * pCryptoSessionHandle)
{
    const uint32_t _cmd_size = (uint32_t)npt_sizeof_ID3D11CryptoSession_GetCryptoSessionHandle(pCryptoSessionHandle);
    struct npt_command_header _hdr = {
        .cmd_type = NPT_CMD_TYPE(255, NPT_IFACE_ID_ID3D11CryptoSession,
                                 NPT_METHOD_ID3D11CryptoSession_GetCryptoSessionHandle),
        .cmd_flags = cmd_flags,
        .object_id = object_id,
        .cmd_size = _cmd_size,
    };
    npt_cs_encoder_write(enc, sizeof(_hdr), &_hdr, sizeof(_hdr));
/* skip pCryptoSessionHandle (output only) */
}

static inline size_t
npt_sizeof_ID3D11CryptoSession_GetCryptoSessionHandle_reply(const HANDLE * pCryptoSessionHandle)
{
    /* Reply sizing reserves an upper bound before the host has filled
     * the data, so union arms size as max-of-arms regardless of the
     * caller's discriminator -- max_mode=1. */
    const int max_mode = 1;
    (void)max_mode;  /* unused when the reply has no struct/union outputs */
    size_t cmd_size = sizeof(struct npt_reply_header);
    cmd_size += sizeof(uint64_t);
    return cmd_size;
}

static inline void
npt_decode_ID3D11CryptoSession_GetCryptoSessionHandle_reply(struct npt_cs_decoder *dec,
                                                            HANDLE * pCryptoSessionHandle)
{
    struct npt_reply_header _reply;
    npt_cs_decoder_read(dec, sizeof(_reply), &_reply, sizeof(_reply));
    if (unlikely(_reply.cmd_type != NPT_CMD_TYPE(255, NPT_IFACE_ID_ID3D11CryptoSession,
                                                  NPT_METHOD_ID3D11CryptoSession_GetCryptoSessionHandle))) {
        /* Host didn't write a reply (decoder fatal, encoder acquire
         * failed, or the reply shmem wasn't populated before the ring
         * head advanced past this command).  Zero reply_type means the
         * reply slot is still at its init value; any other mismatch
         * means reply-stream crossover.  Surface the error to the
         * caller rather than asserting -- the D3D runtime can cope
         * with a failed call, it can't cope with abort(). */
        npt_log("ID3D11CryptoSession_GetCryptoSessionHandle reply mismatch: got 0x%08x expected 0x%08x",
                (unsigned)_reply.cmd_type,
                (unsigned)NPT_CMD_TYPE(255, NPT_IFACE_ID_ID3D11CryptoSession,
                                       NPT_METHOD_ID3D11CryptoSession_GetCryptoSessionHandle));
        return;
    }
    {
        npt_object_id _id;
        npt_decode_uint64_t(dec, &_id);
        if (pCryptoSessionHandle)
            *pCryptoSessionHandle = (HANDLE)(uintptr_t)npt_win32_handle_from_id(_id);
    }
}

static inline void
npt_submit_ID3D11CryptoSession_GetCryptoSessionHandle(struct npt_ring *ring,
                                                      uint32_t cmd_flags,
                                                      npt_object_id object_id,
                                                      HANDLE * pCryptoSessionHandle,
                                                      struct npt_ring_submit_command *submit)
{
    uint8_t local_cmd_data[NPT_SUBMIT_LOCAL_CMD_SIZE];
    void *cmd_data = local_cmd_data;
    size_t cmd_size = npt_sizeof_ID3D11CryptoSession_GetCryptoSessionHandle(pCryptoSessionHandle);
    if (cmd_size > sizeof(local_cmd_data)) {
        cmd_data = malloc(cmd_size);
        if (!cmd_data)
            cmd_size = 0;
    }
    const size_t reply_size = (cmd_flags & NPT_CMD_FLAG_REPLY)
        ? npt_sizeof_ID3D11CryptoSession_GetCryptoSessionHandle_reply(pCryptoSessionHandle)
        : 0;

    struct npt_cs_encoder *enc = npt_ring_submit_command_init(ring, submit, cmd_data, cmd_size, reply_size);
    if (cmd_size) {
        npt_encode_ID3D11CryptoSession_GetCryptoSessionHandle(enc, cmd_flags, object_id, pCryptoSessionHandle);
        npt_ring_submit_command(ring, submit);
        if (cmd_data != local_cmd_data)
            free(cmd_data);
    }
}

static inline void
npt_async_ID3D11CryptoSession_GetCryptoSessionHandle(struct npt_ring *ring,
                                                     npt_object_id object_id,
                                                     HANDLE * pCryptoSessionHandle)
{
    struct npt_ring_submit_command submit;
    npt_submit_ID3D11CryptoSession_GetCryptoSessionHandle(ring, 0, object_id, pCryptoSessionHandle, &submit);
}

static inline void
npt_call_ID3D11CryptoSession_GetCryptoSessionHandle(struct npt_ring *ring,
                                                    npt_object_id object_id,
                                                    HANDLE * pCryptoSessionHandle)
{
    struct npt_ring_submit_command submit;
    npt_submit_ID3D11CryptoSession_GetCryptoSessionHandle(ring, NPT_CMD_FLAG_REPLY, object_id, pCryptoSessionHandle, &submit);
    struct npt_cs_decoder *dec = npt_ring_get_command_reply(ring, &submit);
    if (dec) {
        npt_decode_ID3D11CryptoSession_GetCryptoSessionHandle_reply(dec, pCryptoSessionHandle);
        npt_ring_free_command_reply(ring, &submit);
    }
}


